    edges[edgeCount] = u; flows[edgeCount] = 0; capacities[edgeCount] = 0; nextEdge[edgeCount] = head[v]; head[v] = edgeCount++;
}
bool buildLevelGraph() {
    for (int i=0; i<=totalNodes; i++) level[i] = 0;
    front = rear = 0;
    queueArr[front++] = source;
    level[source] = 1;
    while (rear < front && !level[sink]) {
        int u = queueArr[rear++];
        for (int e = head[u]; e; e = nextEdge[e]) {
