            flows[e] += f;
            flows[e^1] -= f;
            return f;
        }
    }
    return 0;
}
int maxFlow() {
    int totalFlow=0, flowVal;
    while (buildLevelGraph()) {
        for (int i=0; i<=totalNodes; i++) current[i] = head[i];
        while ((flowVal=sendFlow(source, INF))) totalFlow += flowVal;
    }
    return totalFlow;
}

int R;
string grid1[MAXR], grid2[MAXR];

int deltaI[] = {0,1,0,-1};
int deltaJ[] = {1,0,-1,0};

