import java.util.*;
import java.io.*;

public class Main {
    static class Pair {
        int x, y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static final int MAXR = 11;
    static final int MAXN = 1000;
    static final int MAXM = 100100;
    static final int INF = 1 << 29;

    static int[] edges = new int[2 * MAXM];
    static int[] flows = new int[2 * MAXM];
    static int[] capacities = new int[2 * MAXM];
    static int[] nextEdge = new int[2 * MAXM];
    static int[] head = new int[MAXN + 1];
    static int[] current = new int[MAXN + 1];
    static int[] level = new int[MAXN + 1];
    static int[] queueArr = new int[MAXN + 1];

    static int edgeCount, totalNodes, source, sink, front, rear;

    static String[] grid1 = new String[MAXR];
    static String[] grid2 = new String[MAXR];

    static int[] deltaI = {0, 1, 0, -1};
    static int[] deltaJ = {1, 0, -1, 0};

    static int R, T;
    static int zi = 0, zj = 0;

    static int[][][] timeMap = new int[2][MAXR][MAXR];
    static int[][][] nodeID = new int[2][MAXR][MAXR];

    static boolean canTraverse(int i, int j) {
        return (i >= 0 && j >= 0 && i < R && j < R && grid1[i].charAt(j) != 'Y' && grid1[i].charAt(j) != 'Z');
    }

    static void initializeFlow(int nodes, int sNode, int tNode) {
        totalNodes = nodes;
        source = sNode;
        sink = tNode;
        edgeCount = 2;
        Arrays.fill(head, 0);
    }

    static void addFlowEdge(int u, int v, int capVal) {
        edges[edgeCount] = v;
        flows[edgeCount] = 0;
        capacities[edgeCount] = capVal;
        nextEdge[edgeCount] = head[u];
        head[u] = edgeCount++;
        edges[edgeCount] = u;
        flows[edgeCount] = 0;
        capacities[edgeCount] = 0;
        nextEdge[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    static boolean buildLevelGraph() {
        Arrays.fill(level, 0);
        front = 0;
        rear = 0;
        queueArr[front++] = source;
        level[source] = 1;
        while (rear < front && level[sink] == 0) {
            int u = queueArr[rear++];
            for (int e = head[u]; e != 0; e = nextEdge[e]) {
                int v = edges[e];
                if (level[v] == 0 && flows[e] < capacities[e]) {
                    level[v] = level[u] + 1;
                    queueArr[front++] = v;
                }
            }
        }
        return level[sink] != 0;
    }

    static int sendFlow(int u, int flowAmount) {
        if (u == sink) return flowAmount;
        for (int e = current[u]; e != 0; e = current[u] = nextEdge[e]) {
            int v = edges[e];
            if (level[u] < level[v] && flows[e] < capacities[e]) {
                int f = sendFlow(v, Math.min(flowAmount, capacities[e] - flows[e]));
                if (f > 0) {
                    flows[e] += f;
                    flows[e ^ 1] -= f;
                    return f;
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        int flowVal;
        while (buildLevelGraph()) {
            for (int i = 0; i <= totalNodes; i++) {
                current[i] = head[i];
            }
            while ((flowVal = sendFlow(source, INF)) > 0) {
                totalFlow += flowVal;
            }
        }
        return totalFlow;
    }

    static void performBFS(int i, int j, int c) {
        for (int k = 0; k < R; k++) {
            for (int l = 0; l < R; l++) {
                timeMap[c][k][l] = 0;
            }
        }
        timeMap[c][i][j] = 1;
        Queue<Pair> q = new LinkedList<>();
        q.offer(new Pair(i, j));
        while (!q.isEmpty()) {
            Pair p = q.poll();
            int x = p.x;
            int y = p.y;
            if (c == 1 && (timeMap[0][x][y] != 0 && timeMap[0][x][y] <= timeMap[1][x][y])) continue;
            for (int k = 0; k < 4; k++) {
                int ni = x + deltaI[k];
                int nj = y + deltaJ[k];
                if (canTraverse(ni, nj) && timeMap[c][ni][nj] == 0) {
                    timeMap[c][ni][nj] = timeMap[c][x][y] + 1;
                    q.offer(new Pair(ni, nj));
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());

        int totalNodesCount = 0;
        int start = 0;
        int end = 0;

        for (int i = 0; i < R; i++) {
            grid1[i] = br.readLine();
            for (int j = 0; j < R; j++) {
                if (grid1[i].charAt(j) == 'Z') {
                    zi = i;
                    zj = j;
                } else if (grid1[i].charAt(j) != 'Y') {
                    totalNodesCount++;
                    nodeID[0][i][j] = totalNodesCount;
                }
            }
        }

        for (int i = 0; i < R; i++) {
            grid2[i] = br.readLine();
            for (int j = 0; j < R; j++) {
                if (grid2[i].charAt(j) != 'Y' && grid2[i].charAt(j) != 'Z') {
                    totalNodesCount++;
                    nodeID[1][i][j] = totalNodesCount;
                }
            }
        }

        totalNodesCount++;
        start = 0;
        end = totalNodesCount;
        initializeFlow(totalNodesCount, start, end);

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (grid1[i].charAt(j) != 'Z' && grid1[i].charAt(j) != 'Y') {
                    addFlowEdge(start, nodeID[0][i][j], grid1[i].charAt(j) - '0');
                    addFlowEdge(nodeID[1][i][j], end, grid2[i].charAt(j) - '0');
                }
            }
        }

        performBFS(zi, zj, 0);

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (grid1[i].charAt(j) > '0' && grid1[i].charAt(j) <= '9') {
                    performBFS(i, j, 1);
                    for (int ii = 0; ii < R; ii++) {
                        for (int jj = 0; jj < R; jj++) {
                            if (grid2[ii].charAt(jj) > '0' && grid2[ii].charAt(jj) <= '9') {
                                if (timeMap[1][ii][jj] != 0 && (timeMap[0][ii][jj] == 0 || timeMap[0][ii][jj] >= timeMap[1][ii][jj]) && timeMap[1][ii][jj] - 1 <= T) {
                                    addFlowEdge(nodeID[0][i][j], nodeID[1][ii][jj], INF);
                                }
                            }
                        }
                    }
                }
            }
        }

        System.out.println(maxFlow());
    }
}
